		public async Task BlendPixMatchesCpp(CompOp op, float dr, float dg, float db, float da, float sr, float sg, float sb, float sa, int cover, uint r, uint g, uint b, uint a)
		{
			var p = new float[4];
			p[ImageBuffer.OrderR] = dr;
			p[ImageBuffer.OrderG] = dg;
			p[ImageBuffer.OrderB] = db;
			p[ImageBuffer.OrderA] = da;

			BlenderCompOpBGRAFloat.BlendPix(op, p, 0, new ColorF(sr, sg, sb, sa), cover);

			await Assert.That(BitConverter.SingleToUInt32Bits(p[ImageBuffer.OrderR])).IsEqualTo(r);
			await Assert.That(BitConverter.SingleToUInt32Bits(p[ImageBuffer.OrderG])).IsEqualTo(g);
			await Assert.That(BitConverter.SingleToUInt32Bits(p[ImageBuffer.OrderB])).IsEqualTo(b);
			await Assert.That(BitConverter.SingleToUInt32Bits(p[ImageBuffer.OrderA])).IsEqualTo(a);
		}
	}
